static void kg_run__1(fir_t *p, const kg_float *a0_x, kg_float *out);

/* run(float[256]) -> float[241] */
static void kg_run__1(fir_t *p, const kg_float *a0_x, kg_float *out) {
#pragma HLS inline
    (void)p;
    (void)a0_x;
    /* fir.kg:17: +/taps*x@idx */
    for (kg_int i1 = 0; i1 < 241; i1++) {
        #pragma HLS pipeline II=1
        out[i1] = (kg_c_taps[0] * a0_x[kg_c_idx[i1]]);
    }
    for (kg_int i2 = 1; i2 < 16; i2++) {
        #pragma HLS unroll
        for (kg_int i3 = 0; i3 < 241; i3++) {
            #pragma HLS pipeline II=1
            out[i3] = (out[i3] + (kg_c_taps[i2] * a0_x[kg_c_idx[((i2 * 241) + i3)]]));
        }
    }
}

void fir_init(fir_t *p) {
    (void)p;
}

size_t fir_size(void) {
    return sizeof(fir_t);
}

/* the window of entry run: the result of one output from the last 16 samples */
kg_float fir_run_window(const kg_float *win) {
#pragma HLS inline
    kg_float t1 = (kg_c_taps[0] * win[0]);
    t1 = (t1 + (kg_c_taps[1] * win[1]));
    t1 = (t1 + (kg_c_taps[2] * win[2]));
    t1 = (t1 + (kg_c_taps[3] * win[3]));
    t1 = (t1 + (kg_c_taps[4] * win[4]));
    t1 = (t1 + (kg_c_taps[5] * win[5]));
    t1 = (t1 + (kg_c_taps[6] * win[6]));
    t1 = (t1 + (kg_c_taps[7] * win[7]));
    t1 = (t1 + (kg_c_taps[8] * win[8]));
    t1 = (t1 + (kg_c_taps[9] * win[9]));
    t1 = (t1 + (kg_c_taps[10] * win[10]));
    t1 = (t1 + (kg_c_taps[11] * win[11]));
    t1 = (t1 + (kg_c_taps[12] * win[12]));
    t1 = (t1 + (kg_c_taps[13] * win[13]));
    t1 = (t1 + (kg_c_taps[14] * win[14]));
    t1 = (t1 + (kg_c_taps[15] * win[15]));
    return t1;
}

void fir_run(fir_t *p, const kg_float *x /* [256] */, kg_float *out /* [241] */) {
    kg_run__1(p, x, out);
}
